"""Current guide overlay for nonlinear calibration and verified KFM delivery."""
from pathlib import Path
import json,hashlib
import pandas as pd
O=Path('outputs/dataset_inventory_20261101');N=Path('outputs/nonlinear_biomass_calibration_20261102')
def apply(views):
    if not (N/'report_verified.json').exists():return views
    record=json.loads((N/'report_verified.json').read_text())
    for path,h in json.loads((N/'input_hashes.json').read_text()).items():
        assert hashlib.sha256(Path(path).read_bytes()).hexdigest()==h, 'Nonlinear evidence input changed: '+path
    for name,h in record['output_hashes'].items():assert hashlib.sha256((N/name).read_bytes()).hexdigest()==h,name
    receipt=json.loads((N/'kfm_source_receipt.json').read_text());holds=pd.read_csv('outputs/biomass_next_steps_20261102/kfm_year_holds.csv')
    need=holds.biomass_status.eq('original physical-site sizes required');holds['source_receipt_status']='Historical diagnostic or verified zero; no new numerical update';holds.loc[need,'source_receipt_status']='Original urchin workbook received; site/species/date reconciliation pending';holds['delivered_year_present']=holds.year.isin(receipt['actual_years']);holds['new_source']=receipt['file'];holds['biomass_holds_cleared']=False;holds.to_csv(N/'kfm_current_holds.csv',index=False);holds.to_csv(O/'kfm_current_holds.csv',index=False);views['KFM year holds']=holds
    entries=[['B47','2026-11-02','Implementation','Test exact mass aggregation, individual-mass means and empirical count resampling with shared size effects','Conditional nonlinear calibration implemented','Same sites/years; calibration and iterated expansion are diagnostics, not a full nonlinear fit','outputs/nonlinear_biomass_calibration_20261102/README.md'],['B48','2026-11-02','Source receipt','Scott Gabara delivered original 2012–2022 red/purple urchin size workbook','Received and hash-verified; reconciliation pending','Requested years present; distinct site names and exact millimeter sizes available; no biomass holds cleared','outputs/nonlinear_biomass_calibration_20261102/kfm_source_receipt.json'],['B49','2026-11-02','Hold','Keep nonlinear calibration separate from a validated complete raw-data model','Primary and paper unchanged','Fixed support/dispersion/allometry and empirical count support remain conditional; reconstruct KFM donors next','outputs/nonlinear_biomass_calibration_20261102/README.md']]
    p=Path('docs/BIOMASS_ASSUMPTIONS_AND_CHANGES.csv');ledger=pd.read_csv(p);ledger=ledger[~ledger.id.isin(['B47','B48','B49'])];add=pd.DataFrame(entries,columns=ledger.columns);ledger=pd.concat([ledger,add],ignore_index=True).sort_values('id');assert len(ledger)>=49 and ledger.id.is_unique;ledger.to_csv(p,index=False)
    hist=views['Decision history'];hist=hist[~hist.id.isin(['B47','B48','B49'])];add=add.assign(current_interpretation='Current calibration evidence or source receipt; numerical primary holds retained',lifecycle='Retained evidence / scoped decision');hist=pd.concat([hist,add],ignore_index=True).sort_values('id');hist.to_csv(O/'decision_history.csv',index=False);views['Decision history']=hist;views['Biomass assumptions']=ledger
    rules=views['Current rules'].copy();mask=rules.rule_id.eq('R13');rules.loc[mask,'implementation_status']='Joint working model and paired conditional nonlinear calibration checked on six PISCO histories; no primary promotion';rules.loc[mask,'limitation_or_supersedes']='Conditional calibration includes exact aggregation and sample/count resampling; complete nonlinear likelihood, allometric uncertainty, detection and eligibility regeneration remain outside scope';rules.loc[mask,'evidence_path']=str(N/'README.md');rules.to_csv(O/'current_rules.csv',index=False);views['Current rules']=rules
    q=views['Questions'].copy();q.loc[q.issue_id.eq('U08'),'finding']='Scott original urchin workbook received and verified, covering years in all54unresolved donor records; site/species/date reconciliation still pending. Joint working-model nonlinear calibration completed conditionally; total uncertainty remains incomplete.';q.loc[q.issue_id.eq('U08'),'next_action']='Reconcile delivered physical sites and exact millimeter size frequencies with held counts; keep exclusions. Review nonlinear calibration limits before primary promotion.';q.to_csv(O/'unresolved_issues.csv',index=False);views['Questions']=q
    freeze=views['Freeze readiness'].copy();freeze.loc[freeze.item_id.eq('F3'),'latest_status']='Original KFM workbook received; donor reconciliation pending. PISCO support and researcher exclusions unchanged.';freeze.loc[freeze.item_id.eq('F4'),'latest_status']='Joint working likelihood and conditional nonlinear calibration checked; full data-generation, allometry and cross-history covariance limits retained.';freeze.to_csv(O/'freeze_readiness.csv',index=False);views['Freeze readiness']=freeze
    ms=views['Measurement support'].copy();ids=set(holds.loc[need,'series_id']);ms['kfm_delivery_status']=ms.series_id.map(lambda x:'Received; site/species/date matching pending' if x in ids else 'Not affected by this source delivery');ms.to_csv(O/'measurement_support_current.csv',index=False);views['Measurement support']=ms;views['Biomass support']=ms
    for label,name in [('Nonlinear comparison','same_year_comparison.csv'),('Nonlinear calibration','calibration_summary.csv'),('Nonlinear bias','paired_bias_changes.csv'),('Nonlinear iterations','observed_iteration.csv')]:
        df=pd.read_csv(N/name);df.to_csv(O/('nonlinear_'+name),index=False);views[label]=df
    r=pd.DataFrame([dict(source=receipt['file'],received=receipt['received'],rows=receipt['nonempty_rows'],sites=receipt['source_sites'],years=';'.join(map(str,receipt['actual_years'])),status='File received; no biomass holds cleared',scope=receipt['scope'])]);r.to_csv(O/'kfm_source_receipt.csv',index=False);views['KFM source receipt']=r
    guide=O/'README.md';text=guide.read_text().replace('all 46 dated entries','all 49 dated entries').replace('all 43 dated entries','all 49 dated entries');text+='\n## Nonlinear calibration and source receipt\n\n[Current results and figure](../nonlinear_biomass_calibration_20261102/index.html) extend the joint-model review with exact biomass aggregation and sample/count resampling. Same six PISCO histories and45post-protection years; no paper or primary update. Calibration remains conditional, not a complete nonlinear likelihood. Scott’s original urchin-size workbook has arrived and been verified. It covers the requested donor years, but physical-site/species/date matching remains pending; all54biomass donor holds remain until verified. Use the current KFM year-hold and receipt tables rather than older waiting-for-file notes.\n';guide.write_text(text)
    hashes=json.loads((O/'current_decision_inputs.json').read_text());hashes[str(p)]=hashlib.sha256(p.read_bytes()).hexdigest()
    for name in record['output_hashes']:
        path=N/name;hashes[str(path)]=hashlib.sha256(path.read_bytes()).hexdigest()
    (O/'current_decision_inputs.json').write_text(json.dumps(hashes,indent=2))
    return views
